mapper.select:
SELECT cm.id, cm.application_flow, cm.types, cm.user_id, cm.phone, cm.withdrawal, cm.amount_withdrawn, cm.approval_status, cm.Approval_remarks, cm.created_by, cm.created_time, cm.updated_by, cm.updated_time, cm.is_delete, u.username FROM dts_commission_management cm LEFT JOIN dts_user u ON cm.user_id = u.id
AND u.username LIKE concat('%', #{user.username}, '%')
AND cm.phone LIKE concat('%', #{phone}, '%')
AND cm.approval_status LIKE concat('%', #{approvalStatus}, '%')
AND cm.id = #{id}
AND cm.application_flow = #{applicationFlow}
AND cm.types = #{types}
AND cm.user_id = #{userId}
